const b = $input.first().json.body || $input.first().json;
return [{ json: {
  platform: b.platform || 'shopee',
  buyer: b.buyer_name || b.sender || 'Buyer',
  message: b.message || b.text || '',
  order_id: b.order_id || '-'
}}];

const { message } = $input.first().json;
const t = message.toLowerCase();

const KB = [
  {k:['ready','stock','available'], a:'Ready, please order directly. Limited stock.'},
  {k:['ship','shipping','courier','delivery','how long'], a:'Shipped the same day if you order before 3 PM. Estimated 2-5 days depending on the city.'},
  {k:['color','size','variant'], a:'All variants ready. You can pick directly on the product page.'},
  {k:['negotiate','discount','cheaper','lower price'], a:'This is our best price, our margin is thin. Free shipping for orders over Rp 100,000.'},
  {k:['original','authentic','fake','genuine','bpom'], a:'100% original, 7-day warranty. COD available in select cities.'},
  {k:['cod','pay on delivery'], a:'COD available, depending on courier and location. Check at checkout.'},
  {k:['reseller','dropship','wholesale','bulk'], a:'We have a reseller program, chat admin for special pricing.'},
  {k:['hello','hi','hey'], a:'Hello! How can we help? Ask us anything about products, stock, or shipping.'}
];

let best = null, bestLen = 0;
for (const e of KB) {
  for (const k of e.k) {
    if (t.includes(k) && k.length > bestLen) { best = e; bestLen = k.length; }
  }
}

const answer = best ? best.a :
  'Thanks for reaching out. Our team will reply shortly.';

return [{ json: { answer, matched: !!best } }];
